internal static async Task<MortalJointInterfacePublication.Record?> ReadJointInterfaceAtOrdinarySlotAsync(
    FileSystemManager files, FileSystemManager.CanonicalWriteLease lease)
{
    var bytes = await files.ReadFileBytesAsync(lease, StatePath);
    if (bytes is null) return null;
    var marker = StrictJsonAuthority.Deserialize<JsonObject>(CanonicalJsonUtf8.DecodeOneOptionalBom(bytes),
        SharedJsonOptions.PrettyCamelCaseUnsafeRelaxed, "current ordinary-slot joint selector")
        ?? throw Invalid("joint_interface_ordinary_marker_null");
    var jointClaim = marker.ContainsKey("outputBinding") || marker.ContainsKey("niPublication") ||
        marker.ContainsKey("jointTreatment") || marker.ContainsKey("consumedPrivatePaths") || marker.ContainsKey("progression");
    if (marker["schemaVersion"]?.GetValue<int>() != 2)
    {
        if (jointClaim) throw Invalid("joint_interface_selected_parent_version_changed");
        return null; // genuine old non-joint publication, not a claimed NI downgrade
    }
    var original = ReadInspectionSnapshot(files, lease);
    if (original.SessionId != Text(marker, "sessionId") || original.RequestId != Text(marker, "requestId") ||
        original.SnapshotToken != Text(marker, "snapshotToken") || original.TurnNumber != JointInteger(marker, "turn"))
    {
        // A tuple mismatch by itself is not a new operation: one corrupt
        // request/turn field must not request another ordinary I projection.
        // A genuine new original already signed the EXACT prior marker as a
        // baseline before its new GM outputs; use that actual source witness.
        if (!original.CoveredLogicalPaths.Contains(StatePath, StringComparer.Ordinal) ||
            !Same(bytes, original.ReadRequiredBytes(StatePath))) throw Invalid("joint_interface_selector_tuple_conflict");
        return null;
    }
    // Even a claimed legacy child is fully checked before permitting its old
    // writer. Partial deletion/downgrade cannot exploit a null memory cache.
    return await ReadCurrentJointInterfaceDataAsync(files, lease, original.SessionId,
        original.RequestId, original.SnapshotToken, original.TurnNumber);
}

private async Task<IReadOnlyList<ValidationIssue>> ReadMortalJointInterfaceAtGenericSlotAsync()
{
    MortalJointInterfacePublication.Record? current;
    await using (var lease = await _fs.AcquireCanonicalWriteLeaseAsync())
    {
        await RequireNoMortalJointInterfaceRestoreAsync(lease, blockSelectedMissing: true);
        current = await MortalQteDecisionPublication.ReadJointInterfaceAtOrdinarySlotAsync(_fs, lease);
    }
    if (current is not null) return current.Issues;
    return await _validator.ValidateAcceptedTurnInterfacePayloadAsync(); // original public owning lease after inspection closed

private static async Task<CompletedProof> ReadCompletedProofAsync(FileSystemManager fs, FileSystemManager.CanonicalWriteLease lease,
    PendingTurnSnapshotReadAuthority inspection)
{
    var bytes = await fs.ReadFileBytesAsync(lease, StatePath) ?? throw Invalid("missing");
    var root = StrictJsonAuthority.Deserialize<JsonObject>(new UTF8Encoding(false, true).GetString(bytes).TrimStart('\uFEFF'),
        SharedJsonOptions.PrettyCamelCaseUnsafeRelaxed, "T070 common publication evidence") ?? throw Invalid("null");
    if (root["schemaVersion"] is JsonValue version && version.TryGetValue<int>(out var schema) && schema == 2)
        return await ReadJointCompletedProofAsync(fs, lease, inspection, root);
    if (root.Count != Fields.Length || root.Any(pair => !Fields.Contains(pair.Key, StringComparer.Ordinal)) ||
        root["schemaVersion"]?.GetValue<int>() != 1) throw Invalid("shape");
    var payload = root.DeepClone().AsObject(); payload.Remove("fingerprint");
    if (Text(root, "fingerprint") != Fingerprint(payload) || !fs.IsCurrentSessionGeneration(lease, Text(root, "generation")))
        throw Invalid("seal_or_generation");
    var snapshot = ReadSnapshot(fs, lease);
    if (snapshot.Realm != "mortal_world" || inspection.SessionId != snapshot.SessionId || inspection.RequestId != snapshot.RequestId ||
        inspection.SnapshotToken != snapshot.SnapshotToken || inspection.TurnNumber != snapshot.TurnNumber ||
        Text(root, "sessionId") != snapshot.SessionId || Text(root, "requestId") != snapshot.RequestId ||
        Text(root, "snapshotToken") != snapshot.SnapshotToken || root["turn"]?.GetValue<int>() != snapshot.TurnNumber ||
        Text(root, "manifestHash") != Digest(await fs.ReadFileBytesAsync(lease, LiveTurnPreparationService.PendingTurnSnapshotManifestPath)) ||
        Text(root, "authorityHash") != Digest(await fs.ReadFileBytesAsync(lease, PendingTurnSnapshotAuthority.AuthorityPath)) ||
        string.IsNullOrWhiteSpace(Text(root, "inputFingerprint"))) throw Invalid("source_or_receipt");

    issues = await _validator.ValidateGameStateAsync();
}
